// 计算 1 到 n 中数字 0 出现的总次数
ll countZero(ll n) {
    if (n <= 0) return 0;
    int digits[20], len = 0;
    ll temp = n;
    while (temp) {
        digits[len++] = temp % 10;
        temp /= 10;
    }
    ll ans = 0;
    ll tt = n;
    for (int i = len - 1; i >= 0; --i) {
        int d = digits[i];
        ans += dp[i] * d;
        if (d > 0) ans += mid[i];
        tt -= mid[i] * d;
        if (d == 0) ans += tt + 1;
        ans -= mid[i];
    }
    return ans;
